memory = {""}

def get_time():
    return datetime.now().astimezone().strftime("%Y-%m-%d %I:%M:%S %p %Z")

def save_memory(key, value):
    memory[key.lower()] = value
    return f"Saved: {key} = {value}"

def read_memory(key):
    return memory.get(key.lower(), "I don't remember that.")

